// Unit tests of BlobStore for interleavings too narrow to hit reliably
// through HTTP.

import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, it, mock } from 'node:test';

import { BlobStore } from '../src/blobs.js';

describe('BlobStore', () => {
  let dataDir;
  let store;

  beforeEach(async () => {
    dataDir = await fs.mkdtemp(path.join(os.tmpdir(), 'syncbox-store-'));
    store = new BlobStore(dataDir);
  });

  afterEach(async () => {
    mock.restoreAll();
    await fs.rm(dataDir, { recursive: true, force: true });
  });

  it('put() recreates a parent directory pruned by a concurrent delete()', async () => {
    await store.put('dir/old', [Buffer.from('old')]);

    // Make the delete of the directory's last blob land exactly between
    // put()'s mkdir and its rename.
    const rename = fs.rename;
    let interleaved = false;
    mock.method(fs, 'rename', async (from, to) => {
      if (!interleaved) {
        interleaved = true;
        assert.equal(await store.delete('dir/old'), true);
        await assert.rejects(fs.stat(path.join(dataDir, 'blobs', 'dir')), { code: 'ENOENT' });
      }
      return rename(from, to);
    });

    assert.deepEqual(await store.put('dir/new', [Buffer.from('new')]), {
      key: 'dir/new',
      sha256: '11507a0e2f5e69d5dfa40a62a1bd7b6ee57e6bcd85c67c9b8431b36fff21c437',
      size: 3,
    });
    assert.ok(interleaved);
    assert.deepEqual((await store.list()).map((b) => b.key), ['dir/new']);
  });

  it('delete() keeps the blob root itself when it becomes empty', async () => {
    await store.put('only', [Buffer.from('x')]);
    assert.equal(await store.delete('only'), true);
    assert.deepEqual(await fs.readdir(path.join(dataDir, 'blobs')), []);
  });
});
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import fs from 'node:fs/promises';
import http from 'node:http';
import os from 'node:os';
import path from 'node:path';
import { after, before, beforeEach, describe, it } from 'node:test';

import { createServer } from '../src/server.js';

// Sends a request with the path exactly as given: fetch() (and http.request
// with a URL string) would normalise `..` segments and escapes away first.
function rawRequest(baseUrl, method, rawPath, body) {
  const { hostname, port } = new URL(baseUrl);
  return new Promise((resolve, reject) => {
    const req = http.request({ hostname, port, method, path: rawPath }, (res) => {
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => {
        const body = Buffer.concat(chunks);
        const text = body.toString();
        const json = /json/.test(res.headers['content-type'] ?? '') && text ? JSON.parse(text) : undefined;
        resolve({ status: res.statusCode, headers: res.headers, body, text, json });
      });
    });
    req.on('error', reject);
    req.end(body);
  });
}

const sha256 = (data) => createHash('sha256').update(data).digest('hex');

// Percent-encodes every byte, so arbitrary byte sequences can be sent as a key.
const encodeBytes = (bytes) => [...bytes].map((b) => `%${b.toString(16).padStart(2, '0')}`).join('');

// Small deterministic PRNG so the fuzz cases are reproducible.
function prng(seed) {
  let x = seed >>> 0;
  return () => {
    x ^= x << 13;
    x ^= x >>> 17;
    x ^= x << 5;
    return (x >>> 0) / 2 ** 32;
  };
}

describe('HTTP server', () => {
  let server;
  let baseUrl;

  before(async () => {
    server = createServer({ dataDir: '/nonexistent-unused-by-healthz' });
    await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
    baseUrl = `http://127.0.0.1:${server.address().port}`;
  });

  after(async () => {
    server.closeAllConnections();
    await new Promise((resolve) => server.close(resolve));
  });

  it('GET /healthz returns 200', async () => {
    const res = await fetch(`${baseUrl}/healthz`);
    assert.equal(res.status, 200);
    assert.deepEqual(await res.json(), { status: 'ok' });
  });

  it('GET /healthz ignores the query string', async () => {
    const res = await fetch(`${baseUrl}/healthz?probe=1`);
    assert.equal(res.status, 200);
    await res.body?.cancel();
  });

  it('HEAD /healthz returns 200 without a body', async () => {
    const res = await fetch(`${baseUrl}/healthz`, { method: 'HEAD' });
    assert.equal(res.status, 200);
    assert.equal(await res.text(), '');
  });

  it('rejects other methods on /healthz with 405', async () => {
    const res = await fetch(`${baseUrl}/healthz`, { method: 'POST' });
    assert.equal(res.status, 405);
    assert.equal(res.headers.get('allow'), 'GET, HEAD');
    await res.body?.cancel();
  });

  it('returns 404 for unknown paths', async () => {
    const res = await fetch(`${baseUrl}/no-such-endpoint`);
    assert.equal(res.status, 404);
    await res.body?.cancel();
  });
});

describe('blob endpoints', () => {
  let server;
  let baseUrl;
  let dataDir;
  let tmp;

  before(async () => {
    tmp = await fs.mkdtemp(path.join(os.tmpdir(), 'syncbox-blobs-'));
  });

