  describe('directory traversal in key', () => {
    const del = (rawKey) => rawRequest(baseUrl, 'DELETE', `/blobs/${rawKey}`);
    const methods = {
      PUT: (rawKey) => put(rawKey, 'escaped'),
      GET: (rawKey) => get(rawKey),
      HEAD: (rawKey) => get(rawKey, 'HEAD'),
      DELETE: (rawKey) => del(rawKey),
    };
    const traversalKeys = {
      'bare parent segment': '..',
      'leading parent segment': '../outside/secret',
      'parent segments in the middle': 'a/b/../../../outside/secret',
      'trailing parent segment': 'a/..',
      'percent-encoded dots': '%2e%2e/outside/secret',
      'mixed-case percent-encoded dots': '%2E%2e%2Foutside%2Fsecret',
      'half-encoded dots': '.%2e/outside/secret',
      'encoded slashes around parent segment': 'a%2F..%2F..%2Foutside%2Fsecret',
      'dot segment': './a',
      'absolute path': '/etc/passwd',
      'encoded absolute path': '%2Fetc%2Fpasswd',
      'double slash absolute path': '//etc/passwd',
      'NUL byte before a parent segment': 'a%00/../b',
      'lone surrogate': '%ED%A0%80',
      'invalid UTF-8 after decoding': '%C0%AE%C0%AE/outside',
      'malformed percent-encoding': '%2e%2',
    };

    let outside;
    beforeEach(async () => {
      // A sibling of the data dir that a successful escape would reach.
      outside = path.join(path.dirname(dataDir), 'outside');
      await fs.rm(outside, { recursive: true, force: true });
      await fs.mkdir(outside);
      await fs.writeFile(path.join(outside, 'secret'), 'top secret');
    });

    for (const [method, send] of Object.entries(methods)) {
      for (const [name, rawKey] of Object.entries(traversalKeys)) {
        it(`${method} rejects ${name} with 400`, async () => {
          const res = await send(rawKey);
          assert.equal(res.status, 400, `${method} /blobs/${rawKey}`);
          if (method !== 'HEAD') assert.match(res.json.error, /invalid key/);
        });
      }
    }

    it('leaves the filesystem outside the blob root untouched', async () => {
      for (const send of Object.values(methods)) {
        for (const rawKey of Object.values(traversalKeys)) await send(rawKey);
      }
      assert.deepEqual(await fs.readdir(outside), ['secret']);
      assert.equal(await fs.readFile(path.join(outside, 'secret'), 'utf8'), 'top secret');
      for (const name of await fs.readdir(dataDir)) assert.ok(['blobs', 'tmp'].includes(name), name);
      assert.deepEqual((await list()).json, []);
    });

    it('does not follow a symlink inside the blob root that points outside it', async () => {
      await fs.mkdir(path.join(dataDir, 'blobs'), { recursive: true });
      await fs.symlink(outside, path.join(dataDir, 'blobs', 'link'));

      const got = await get('link/secret');
      assert.equal(got.status, 400);
      assert.doesNotMatch(got.text, /top secret/);
      assert.equal((await put('link/secret', 'pwned')).status, 400);
      assert.equal((await put('link/new/file', 'pwned')).status, 400);
      assert.equal((await del('link/secret')).status, 400);

      assert.deepEqual(await fs.readdir(outside), ['secret']);
      assert.equal(await fs.readFile(path.join(outside, 'secret'), 'utf8'), 'top secret');
    });

    it('still accepts keys that merely contain dots', async () => {
      for (const key of ['...', '..a', 'a..', 'a/..b/c', '.hidden', 'a/.b', 'v1.2..3']) {
        const res = await put(encodeURIComponent(key), key);
        assert.equal(res.status, 201, key);
        assert.equal((await get(encodeURIComponent(key))).text, key);
      }
    });
  });
});
});
